// Đo lường chính xác các mốc thời gian tải trang bằng Performance Navigation Timing API (TypeScript)
export function logPageLoadMetrics() {
  if (typeof window === 'undefined') return;

  window.addEventListener('load', () => {
    const [navEntry] = performance.getEntriesByType('navigation') as PerformanceNavigationTiming[];
    if (!navEntry) return;

    const metrics = {
      dnsLookup: navEntry.domainLookupEnd - navEntry.domainLookupStart,
      tcpHandshake: navEntry.connectEnd - navEntry.connectStart,
      ttfb: navEntry.responseStart - navEntry.requestStart,
      contentDownload: navEntry.responseEnd - navEntry.responseStart,
      domInteractive: navEntry.domInteractive - navEntry.startTime,
      domComplete: navEntry.domComplete - navEntry.startTime,
    };

    console.table(metrics);
  });
}

