// So sánh thao tác gây Reflow liên tục vs Tối ưu bằng CSS Transform GPU (TypeScript)

// ❌ SAI: Thay đổi 'top' và 'left' gây Reflow và Repaint trên từng frame
function animateBoxBad(element: HTMLElement, targetX: number) {
  let currentX = 0;
  const interval = setInterval(() => {
    currentX += 5;
    element.style.left = `${currentX}px`; // GÂY REFLOW TRÊN TỪNG FRAME!
    if (currentX >= targetX) clearInterval(interval);
  }, 16);
}

// ✅ ĐÚNG: Sử dụng transform (chỉ chạy trên GPU Compositor, zero Reflow, zero Repaint)
function animateBoxGood(element: HTMLElement, targetX: number) {
  element.style.transition = 'transform 0.3s cubic-bezier(0.16, 1, 0.3, 1)';
  element.style.willChange = 'transform';
  element.style.transform = `translate3d(${targetX}px, 0, 0)`;
}

