import { onCLS, onINP, onLCP, onTTFB, Metric } from 'web-vitals';

interface VitalsPayload {
  metricName: string;
  value: number;
  rating: 'good' | 'needs-improvement' | 'poor';
  navigationType: string;
}

function sendMetric(metric: Metric) {
  const payload: VitalsPayload = {
    metricName: metric.name,
    value: metric.value,
    rating: metric.rating,
    navigationType: (metric.entries[0] as PerformanceNavigationTiming)?.type || 'navigate',
  };

  navigator.sendBeacon('/api/telemetry/vitals', JSON.stringify(payload));
}

export function setupVitals() {
  onTTFB(sendMetric);
  onLCP(sendMetric);
  onINP(sendMetric);
  onCLS(sendMetric);
}

// So sánh Layout Thrashing vs Batching Read/Write Tối Ưu (TypeScript)
const elements = Array.from(document.querySelectorAll('.card')) as HTMLElement[];

// ❌ SAI: Gây Layout Thrashing nghiêm trọng do xen kẽ Read và Write
function resizeCardsBad() {
  elements.forEach((el) => {
    const width = el.offsetWidth; // READ -> Kích hoạt Forced Reflow!
    el.style.height = `${width * 0.75}px`; // WRITE
  });
}

// ✅ ĐÚNG: Tách rời hoàn toàn pha ĐỌC và pha GHI (Zero Thrashing)
function resizeCardsOptimized() {
  // Pha 1: Đọc toàn bộ dữ liệu từ DOM (trình duyệt chỉ Reflow 1 lần)
  const newHeights = elements.map((el) => el.offsetWidth * 0.75);

  // Pha 2: Ghi toàn bộ dữ liệu vào DOM trong requestAnimationFrame
  requestAnimationFrame(() => {
    elements.forEach((el, index) => {
      el.style.height = `${newHeights[index]}px`;
    });
  });
}

