export const BadUsageExample = ({ a, b }: { a: number; b: number }) => {
  // ❌ SAI: Phép tính cơ bản (O(1)), chi phí so sánh deps còn nặng hơn phép cộng!
  const sum = useMemo(() => a + b, [a, b]);

