const onRenderCallback: ProfilerOnRenderCallback = (
  id, // id của cây Profiler vừa commit
  phase, // 'mount' hoặc 'update'
  actualDuration, // Thời gian thực tế render commit này (ms)
  baseDuration, // Thời gian ước tính render không memo (ms)
  startTime, // Thời điểm React bắt đầu render
  commitTime // Thời điểm React commit vào DOM
) => {
  if (actualDuration > 16) { // Cảnh báo các render vượt quá 1 frame (16.6ms)
    console.warn(`[Slow Render Alert] Component: ${id} | Phase: ${phase} | Duration: ${actualDuration.toFixed(2)}ms`);
