'use client';

import { useReportWebVitals } from 'next/web-vitals';

export function WebVitalsReporter() {
  useReportWebVitals((metric) => {
    // Chỉ gửi dữ liệu trong môi trường production
    if (process.env.NODE_ENV !== 'production') return;

    const telemetryData = {
      id: metric.id,
      name: metric.name,
      value: metric.value,
      rating: metric.rating, // 'good' | 'needs-improvement' | 'poor'
      navigationType: metric.navigationType,
      pathname: window.location.pathname,
      connectionType: (navigator as any).connection?.effectiveType || 'unknown',
    };

    const blob = new Blob([JSON.stringify(telemetryData)], { type: 'application/json' });
    // sendBeacon đảm bảo dữ liệu được gửi ngay cả khi người dùng đóng tab trình duyệt
    navigator.sendBeacon('/api/rum/collect', blob);
  });

  return null;
}

// Bảng đối chiếu ngưỡng kỹ thuật và hàm kiểm tra trạng thái CWV (TypeScript)
export type MetricRating = 'good' | 'needs-improvement' | 'poor';

export const CWV_THRESHOLDS = {
  LCP: { good: 2500, poor: 4000 }, // mili-giây
  INP: { good: 200, poor: 500 },   // mili-giây
  CLS: { good: 0.1, poor: 0.25 },  // điểm số không đơn vị
};

export function evaluateMetric(name: 'LCP' | 'INP' | 'CLS', value: number): MetricRating {
  const config = CWV_THRESHOLDS[name];
  if (value <= config.good) return 'good';
  if (value <= config.poor) return 'needs-improvement';
  return 'poor';
}

