// Đăng ký sự kiện chạm vuốt mượt mà không chặn luồng cuộn (TypeScript)
export function attachSmoothTouchTracker(element: HTMLElement) {
  let startY = 0;

  // Gắn cờ { passive: true } cam kết không gọi preventDefault(), cuộn trang siêu mượt
  element.addEventListener(
    'touchstart',
    (e: TouchEvent) => {
      startY = e.touches[0].clientY;
      console.log('Touch start at:', startY);
    },
    { passive: true }
  );

  element.addEventListener(
    'touchmove',
    (e: TouchEvent) => {
      const currentY = e.touches[0].clientY;
      const deltaY = currentY - startY;
      // e.preventDefault(); // NẾU GỌI Ở ĐÂY SẼ BỊ TRÌNH DUYỆT BÁO LỖI WARNING VÀ VÔ HIỆU HÓA
      console.log('User swiped delta:', deltaY);
    },
    { passive: true }
  );
}

