// Thuật toán tính toán phân vị P99 chuẩn xác từ mảng Histogram Buckets (TypeScript)
interface HistogramBucket {
  upperLimitMs: number; // Ngưỡng trên của bucket (ví dụ: 50ms, 100ms, 200ms, 500ms...)
  count: number;        // Số lượng requests rơi vào khoảng này
}

export function calculateP99FromHistogram(buckets: HistogramBucket[]): number {
  // 1. Tính tổng số lượng mẫu thu thập được (N)
  const totalCount = buckets.reduce((acc, b) => acc + b.count, 0);
  if (totalCount === 0) return 0;

  // 2. Xác định thứ hạng của phân vị thứ 99
  const p99Rank = Math.ceil(totalCount * 0.99);

  // 3. Duyệt tích lũy qua các buckets để tìm bucket chứa mẫu p99
  let accumulatedCount = 0;
  for (const bucket of buckets) {
    accumulatedCount += bucket.count;
    if (accumulatedCount >= p99Rank) {
      return bucket.upperLimitMs; // Trả về ngưỡng thời gian của bucket chứa p99
    }
  }

  return buckets[buckets.length - 1].upperLimitMs;
}

