// Cấu hình các chiến lược Caching tiêu chuẩn với Workbox trong Service Worker (TypeScript)
import { registerRoute } from 'workbox-routing';
import { StaleWhileRevalidate, CacheFirst, NetworkFirst } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';

// 1. Chiến lược Cache-First cho Fonts và Static Images (Lưu 30 ngày)
registerRoute(
  ({ request }) => request.destination === 'image' || request.destination === 'font',
  new CacheFirst({
    cacheName: 'static-assets-cache',
    plugins: [
      new ExpirationPlugin({ maxEntries: 60, maxAgeSeconds: 30 * 24 * 60 * 60 }),
    ],
  })
);

// 2. Chiến lược Stale-While-Revalidate cho API Danh Sách Sản Phẩm
registerRoute(
  ({ url }) => url.pathname.startsWith('/api/products'),
  new StaleWhileRevalidate({
    cacheName: 'api-products-cache',
    plugins: [
      new ExpirationPlugin({ maxEntries: 100, maxAgeSeconds: 24 * 60 * 60 }),
    ],
  })
);

// 3. Chiến lược Network-First cho API Đơn Hàng / Thông Báo (Fallback sang Cache nếu offline)
registerRoute(
  ({ url }) => url.pathname.startsWith('/api/user/orders'),
  new NetworkFirst({
    cacheName: 'api-orders-cache',
    networkTimeoutSeconds: 3, // Nếu quá 3s mạng chậm thì fallback về cache
  })
);

