// Cắt nhỏ Long Task an toàn bằng scheduler.yield() kèm Fallback MessageChannel (TypeScript)
export async function yieldToMain(): Promise<void> {
  // 1. Sử dụng Scheduler API hiện đại nếu trình duyệt hỗ trợ
  if ('scheduler' in window && 'yield' in (window as any).scheduler) {
    return await (window as any).scheduler.yield();
  }

  // 2. Fallback hiệu năng cao dùng MessageChannel (nhanh hơn setTimeout 0ms)
  return new Promise((resolve) => {
    const channel = new MessageChannel();
    channel.port1.onmessage = () => resolve();
    channel.port2.postMessage(null);
  });
}

// Xử lý 20.000 bản ghi mà không làm nghẽn Main Thread, giữ INP < 50ms
export async function processLargeDatasetNonBlocking<T>(items: T[], processFn: (item: T) => void) {
  let lastYieldTime = performance.now();

  for (let i = 0; i < items.length; i++) {
    processFn(items[i]);

    // Cứ sau mỗi 16ms (1 khung hình), chủ động nhường quyền cho trình duyệt vẽ UI
    if (performance.now() - lastYieldTime > 16) {
      await yieldToMain();
      lastYieldTime = performance.now();
    }
  }
}

// Đo lường và gắn Trace ID bóc tách chính xác độ trễ API End-to-End (TypeScript)
export async function diagnosticFetch(url: string, options: RequestInit = {}) {
  const traceId = `trace-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
  const startTime = performance.now();

  const response = await fetch(url, {
    ...options,
    headers: {
      ...options.headers,
      'x-client-trace-id': traceId, // Header liên kết với log Backend OpenTelemetry
    },
  });

  const ttfbTime = performance.now();
  const ttfbDuration = ttfbTime - startTime;

  // Đo thời gian tải xong dữ liệu thô và parse JSON
  const data = await response.json();
  const totalDuration = performance.now() - startTime;
  const downloadAndParseDuration = totalDuration - ttfbDuration;

  console.table({
    url,
    traceId,
    status: response.status,
    'TTFB (Server Processing)': `${ttfbDuration.toFixed(2)} ms`,
    'Content Download & Parse': `${downloadAndParseDuration.toFixed(2)} ms`,
    'Total Latency': `${totalDuration.toFixed(2)} ms`,
    'Payload Size (approx)': `${(JSON.stringify(data).length / 1024).toFixed(2)} KB`,
  });

  return data;
}
